NAME = 'CzeCSP: Czech Český studijní překlad'
BOOK = 'Ruth'

CHAPTERS = {
    1: {
        1: 'I stalo se za dnů, kdy soudili soudcové a v zemi nastal hlad, že jeden muž odešel z judského Betléma, aby pobýval jako cizinec na moábských polích -- on, jeho žena i jeho dva synové.',
        2: 'Jméno toho muže bylo Elímelek, jméno jeho ženy Noemi a jména jeho dvou synů Machlón a Kiljón, Efratejci z judského Betléma. Přišli na moábská pole a přebývali tam.',
        3: 'Potom Elímelek, Noemin muž, zemřel a ona zůstala sama se svými dvěma syny.',
        4: 'Ti si vzali moábské ženy (jméno jedné bylo Orpa a jméno té druhé Rút) a pobývali tam asi deset let.',
        5: 'Pak zemřeli dokonce i ti dva, Machlón a Kiljón, a tak ta žena zůstala sama bez svých dvou dětí a bez svého muže.',
        6: 'Tu povstala ona i její snachy a navrátila se z moábských polí. V moábské krajině se totiž doslechla, že Hospodin navštívil svůj lid, ⌈aby mu dal chléb.⌉',
        7: 'Odešla z toho místa, kde přebývala, a její dvě snachy s ní. Vydaly se na cestu zpět do judské země.',
        8: 'Tehdy řekla Noemi svým dvěma snachám: Jděte, vraťte se každá do domu své matky. Ať vám Hospodin prokáže milosrdenství, podobně jako jste vy jednaly s těmi, kdo zemřeli, i se mnou.',
        9: 'Hospodin vám dá, abyste nalezly odpočinutí každá v domě svého muže. A políbila je. Ony ⌈pozvedly svůj hlas a rozplakaly se.⌉',
        10: 'Řekly jí: Přece se spolu s tebou vrátíme ke tvému lidu.',
        11: 'Ale Noemi odpověděla: Vraťte se moje dcery. Proč byste chodily se mnou? Cožpak se mi znovu objeví v lůně synové a budou vám dáni za muže?',
        12: 'Vraťte se moje dcery, jděte, protože už jsem stará. Nejsem na vdávání. I kdybych si namlouvala: Mám naději a dokonce ⌈se této noci vdala⌉ a navíc bych zplodila syny,',
        13: 'zdali proto budete trpělivě čekat až do doby, kdy vyrostou? Cožpak se kvůli tomu budete zdráhat vdát? Ne, moje dcery, vždyť ⌈je mi tuze hořko, více než vám,⌉ protože na mě dopadla Hospodinova ruka.',
        14: 'Ony nato ⌈pozvedly svůj hlas a znovu se rozplakaly.⌉ Orpa svou tchýni políbila, ale Rút ⌈k ní přilnula.⌉',
        15: 'Ta řekla: Hle, tvá švagrová se obrátila ke svému lidu a ke svým bohům. Obrať se i ty za svou švagrovou.',
        16: 'Avšak Rút odpověděla: ⌈Nenaléhej na mě,⌉ abych tě opustila a odvrátila se od cesty za tebou, protože ⌈kam půjdeš, půjdu i já, a kde zůstaneš,⌉ zůstanu také; tvůj lid bude mým lidem a tvůj Bůh mým Bohem.',
        17: 'Kde zemřeš, zemřu já a tam budu pohřbena. Ať mi tak učiní Hospodin a ještě přidá, že jedině smrt ⌈mě od tebe oddělí.⌉',
        18: 'Noemi viděla, že je odhodlaná jít s ní, a přestala ji přemlouvat.',
        19: 'Tak šly obě dvě, až přišly do Betléma. I stalo se, jakmile přišly do Betléma, že se kvůli nim shluklo celé to město a ženy řekly: Není tohle Noemi?',
        20: 'Ona jim však odpověděla: Nenazývejte mě Noemi. Nazývejte mě Mara, protože mi Všemohoucí způsobil velikou hořkost.',
        21: 'Já jsem odešla plná a Hospodin mě přivedl zpět prázdnou. Proč mě nazýváte Noemi, když Hospodin svědčí proti mně a Všemohoucí se mnou zle jedná?',
        22: 'A tak se Noemi vrátila a s ní se vrátila její snacha, Moábka Rút, z moábských polí. Přišly do Betléma na počátku sklizně ječmene.',
    },
    2: {
        1: 'Noemi měla příbuzného ze strany svého muže, ⌈mocného a zdatného člověka⌉ z Elímelekovy čeledi jménem Bóaz.',
        2: 'Moábka Rút řekla Noemi: Dovol, ať jdu na pole a posbírám klasy za někým, v jehož očích naleznu milost. A ona jí odpověděla: Běž, má dcero.',
        3: 'Šla, až došla na pole, a sbírala za ženci. Ocitla se náhodou na dílu pole patřícím Bóazovi, jenž byl z Elímelekovy čeledi.',
        4: 'Bóaz právě přišel z Betléma a řekl žencům: ⌈Hospodin s vámi.⌉ Oni mu odpověděli: Hospodin ti požehnej.',
        5: 'Bóaz se pak zeptal svého služebníka, který byl ustanoven nad ženci: Čí je tahle dívka?',
        6: 'A ten nad ženci ustanovený služebník mu odpověděl. Řekl: To je moábská dívka, která se vrátila spolu s Noemi z moábské krajiny.',
        7: 'Řekla mi: Dovol, ať sbírám a shromáždím, co zbylo ⌈v pokosech⌉ za ženci. ⌈Přišla a zůstala tu od samého rána až do této chvíle.⌉ Jen ⌈chvilku pobyla doma.⌉',
        8: 'Bóaz řekl Rút: Slyšela jsi přece, má dcero, ať nechodíš sbírat na jiné pole. Již odsud neodcházej. Přidrž se nyní mých služek.',
        9: 'Zaměř své oči na pole, které budou sklízet, a choď za nimi. Vždyť přikazuji služebníkům, aby se tě nedotýkali. A budeš– li mít žízeň, jdi k nádobám a napij se z té, kterou služebníci načerpají.',
        10: 'Tehdy padla na tvář, poklonila se k zemi a zeptala se ho: Jak to, že jsem nalezla milost ve tvých očích, že sis mě všiml, i když jsem cizinka?',
        11: 'Bóaz jí odpověděl. Řekl: Je mi dobře známo všechno, co jsi udělala pro svou tchýni po smrti svého muže; že jsi opustila svého otce, svou matku i svou rodnou zemi a odešla k lidu, který jsi nikdy dříve neznala.',
        12: 'Ať Hospodin odplatí tvůj skutek a ať je dovršená tvá odměna od Hospodina, Boha Izraele, pod jehož křídla jsi přišla najít útočiště.',
        13: 'Nato řekla: ⌈Kéž naleznu milost ve tvých očích,⌉ můj pane, protože jsi mne potěšil a protože ⌈jsi mluvil k srdci⌉ své otrokyně, ačkoliv já nejsem rovna žádné tvé otrokyni.',
        14: 'V době jídla jí Bóaz řekl: Přistup sem, pojez chléb a namoč si sousto v octě. Posadila se poblíž ženců. Nabídl jí pražené zrní a ona pojedla, nasytila se a ještě jí zbylo.',
        15: 'Pak vstala, aby sbírala. Bóaz přikázal svým služebníkům: I když bude sbírat ⌈v pokosech,⌉ neponižujte ji.',
        16: 'Spíš pro ni i schválně upouštějte z hrstí a nechte ji, ať sbírá a nenapomínejte ji.',
        17: 'Tak sbírala na poli až do večera a to, co nasbírala, vymlátila. Byla toho asi éfa ječmene.',
        18: 'Odnesla si to a přišla do města. Když její tchýně viděla, co nasbírala, a když vyndala a dala jí, co jí zbylo po nasycení,',
        19: 'tu se jí tchýně zeptala: Kde jsi dnes sbírala, kde jsi pracovala? Buď požehnán ten, kdo si tě všiml. Oznámila tedy tchýni, u koho pracovala: Jméno toho muže, u kterého jsem dnes pracovala, zní Bóaz.',
        20: 'Nato Noemi své snaše řekla: On ⌈je požehnaný Hospodinu,⌉ který neodňal své milosrdenství živým ani mrtvým. Noemi jí dále řekla: Ten muž je náš příbuzný, je jedním z našich vykupitelů.',
        21: 'Moábka Rút pak řekla: Dokonce mi pověděl i toto: Přidrž se služebníků, které mám, dokud nebude celá moje sklizeň dokončena.',
        22: 'Tehdy Noemi řekla své snaše Rút: Dobře, má dcero, že budeš vycházet s jeho služkami a nebudou na tebe dorážet na jiném poli.',
        23: 'Přidržela se tedy Bóazových služek, aby sbírala, až do konce sklizně ječmene a pšenice. Přitom bydlela se svou tchýní.',
    },
    3: {
        1: 'Její tchýně Noemi jí řekla: Má dcero, ne měla bych snad pro tebe vyhledat místo odpočinku, kde by se ti dobře vedlo?',
        2: 'Vždyť Bóaz, s jehož služkami jsi byla, je náš příbuzný. Pohleď, v noci bude provívat na humně ječmen.',
        3: 'Umyj se tedy, pomaž se, vezmi na sebe své oděvy a sestup na humno, ale nedávej se tomu muži poznat, ⌈dokud nedojí a nedopije.⌉',
        4: 'Až si půjde lehnout, zjisti místo, kde leží, jdi, odhal jeho nohy a ulehni. On ti oznámí, co máš dělat.',
        5: 'Ona jí nato odpověděla: Udělám všechno, co mi řekneš.',
        6: 'Pak sestoupila na humno a udělala všechno, co jí její tchýně přikázala.',
        7: 'Bóaz pojedl, napil se a ⌈bylo mu dobře u srdce.⌉ Potom si šel lehnout na kraj hromady obilí. A ona potají přišla, odhalila jeho nohy a ulehla.',
        8: 'I stalo se uprostřed noci, že se ten muž otřásl, převalil se a vida: V nohách mu leží žena.',
        9: 'Zeptal se: Kdo jsi? Ona odpověděla: Jsem Rút, tvá služebnice. ⌈Rozprostři své křídlo nad⌉ svou služebnicí, vždyť jsi vykupitel.',
        10: 'On nato řekl: ⌈Jsi požehnaná Hospodinu,⌉ má dcero. Dobře jsi udělala. Tvé poslední milosrdenství je větší nežli první, když nechodíš za mládenci, ať chudými či bohatými.',
        11: 'A nyní se, má dcero, neboj. Udělám pro tebe všechno, co řekneš, protože ⌈celé naše město⌉ ví, že jsi zdatná žena.',
        12: 'Ano, opravdu jsem vykupitel. Je však ještě jiný vykupitel, bližší než já.',
        13: 'Zůstaň tu přes noc. A ráno, jestliže ⌈tě on vykoupí,⌉ dobře, ať vykoupí. A pokud si tě nebude přát vykoupit, vykoupím tě tedy já, jakože živ je Hospodin. Spi až do rána.',
        14: 'A tak spala do rána v jeho nohách. Vstala však dříve, než by někdo mohl rozeznat svého bližního. Bóaz si myslel: Jen ať se nikdo nedozví, že na humno přišla žena.',
        15: 'Řekl ještě: Podej mi plachetku, kterou máš na sobě, a podrž ji. Podržela ji tedy a on naměřil ⌈šest měr ječmene⌉ a naložil to na ni. ⌈Pak šel do města.',
        16: 'Ona přišla⌉ ke své tchýni a ta se zeptala: ⌈Jak jsi na tom,⌉ má dcero? Ona jí oznámila vše, jak s ní ten muž jednal.',
        17: 'Řekla: Dal mi těchto šest měr ječmene, neboť mi pověděl: Nepůjdeš ke své tchýni s prázdnou.',
        18: 'Noemi pravila: Musíš počkat, má dcero, než se dozvíš, jak ta záležitost dopadne, protože ten muž nebude mít klid, pokud tu záležitost dnes nedotáhne do konce.',
    },
    4: {
        1: 'Bóaz mezitím vystoupil do brány a posadil se tam. Vykupitel, o němž Bóaz mluvil, tudy zrovna procházel. Zavolal tedy: Hej ty, zajdi sem a posaď se tu někde. A on zašel a usedl.',
        2: 'Bóaz přibral deset mužů ze starších toho města a řekl jim: Zasedněte tu. Oni se posadili.',
        3: 'Tomu vykupiteli řekl: Noemi, která se vrátila z moábské krajiny, prodává díl pole, které patřilo našemu bratru Elímelekovi.',
        4: 'A tak jsem si řekl, že ⌈ti to dám na vědomí:⌉ Kup jej před těmito přísedícími a před staršími mého lidu. Jestliže vykoupíš, vykup. Ale pokud nevykoupíš, oznam mi to, ⌈ať to vím. Vždyť⌉ není, kdo ho smí vykoupit, kromě tebe a mne po tobě. On odpověděl: Já jej vykoupím.',
        5: 'Bóaz řekl: V den, kdy koupíš to pole z ruky Noemi, ⌈kupuješ je i s Moábkou Rút,⌉ ženou zemřelého, abys dal povstat jménu zemřelého v jeho dědictví.',
        6: 'Ten vykupitel odpověděl: Nemohu to pro sebe vykoupit, jinak uvrhnu do zkázy vlastní dědictví. ⌈Nárokuj pro sebe mé výkupní právo⌉ ty, protože já vykoupit nemohu.',
        7: 'Dříve se dělalo v Izraeli při vykupování a při směně toto: Na potvrzení každého jednání zul jeden svůj sandál a dal ho druhému. Toto bývalo osvědčení v Izraeli.',
        8: 'Vykupitel tedy řekl Bóazovi: Kup to pro sebe. A zul si sandál.',
        9: 'Bóaz řekl starším a všemu lidu: Jste mi dnes svědky, že jsem koupil z ruky Noemi všechno, co patřilo Elímelekovi, a všechno, co patřilo Kiljónovi a Machlónovi.',
        10: 'Také Machlónovu ženu, Moábku Rút, jsem koupil za ženu pro sebe, abych dal povstat jménu zemřelého v jeho dědictví a aby nebylo vyhlazeno jméno zemřelého z jeho bratrů a z ⌈jeho domovského města.⌉ Dnes jste toho svědky.',
        11: 'Nato řekl všechen lid, který byl v bráně, a starší: ⌈ Jsme svědky.⌉ Dej Hospodin té ženě, která přichází do tvého domu, aby byla jako Ráchel a jako Lea, které obě vystavěly Izraelův dům. Jednej v Efratě udatně a zjednej si v Betlémě jméno.',
        12: 'Ať je tvůj dům z potomstva, které ti Hospodin dá z této dívky, jako dům Peresa, kterého porodila Támar Judovi.',
        13: 'Tak si Bóaz vzal Rút a stala se jeho ženou. Vešel k ní a Hospodin jí dal otěhotnět a ona porodila syna.',
        14: 'Ženy tehdy řekly Noemi: Požehnaný Hospodin, jenž ti dnes neodepřel vykupitele. Ať se jeho jméno vyhlašuje v Izraeli.',
        15: 'I stane se obnovením tvé duše, aby pečoval o tvé šediny, protože ho porodila tvá snacha, která tě miluje. Ona je pro tebe lepší než sedm synů.',
        16: 'Noemi dítě vzala, položila si ho na klín a stala se mu vychovatelkou.',
        17: 'A sousedky mu daly jméno se slovy: Noemi se narodil syn. A nazvaly ho jménem Obéd. On je otec Jišaje, otce Davidova.',
        18: 'A toto je rodopis Peresův: Peres zplodil Chesróna,',
        19: 'Chesrón zplodil Ráma, Rám zplodil Amínadaba,',
        20: 'Amínadab zplodil Nachšóna, Nachšón zplodil Salmu,',
        21: 'Salmón zplodil Bóaza, Bóaz zplodil Obéda,',
        22: 'Obéd zplodil Jišaje, Jišaj zplodil Davida.',
    },
}
